-- ---------------------------------------------------------------- many-to-many link tables
-- Articles › Audience (many)
create table public.kb_articles_audience_group (
  record_id bigint not null references public.kb_articles (id) on delete cascade,
  target_id smallint not null references public.groups (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (record_id, target_id)
);
create index on public.kb_articles_audience_group (target_id);
comment on table public.kb_articles_audience_group is 'Articles › Audience';
alter table public.kb_articles_audience_group enable row level security;
create policy "view" on public.kb_articles_audience_group for select to authenticated using (exists (select 1 from public.kb_articles r where r.id = record_id));
create policy "change" on public.kb_articles_audience_group for insert to authenticated with check (exists (select 1 from public.kb_articles r where r.id = record_id) and (select app.can_do('kb_articles', 'modify')));
create policy "remove" on public.kb_articles_audience_group for delete to authenticated using (exists (select 1 from public.kb_articles r where r.id = record_id) and (select app.can_do('kb_articles', 'modify')));

